begin;
create extension if not exists pgtap with schema extensions;
select plan(26);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is(public.ai_workspace()->'preferences'->>'enabled','false','AI defaults off');
select is(public.ai_workspace()->'preferences'->>'photo_analysis','false','Photos require separate consent');
select is(public.ai_workspace()->'preferences'->>'revision','0','Unsaved settings have revision zero');
select throws_ok($$select public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','claude-haiku-4-5-20251001',100,3000000)$$,'42501',null,'Clients cannot reserve their own billing');
select throws_ok($$select public.finish_ai_usage(gen_random_uuid(),'failed',null,null,null)$$,'42501',null,'Clients cannot erase their charges');
select throws_ok($$select public.save_ai_preferences('{}',0)$$,'22023','invalid_ai_preferences','Missing booleans rejected');
select is((public.save_ai_preferences((public.ai_workspace()->'preferences') || '{"enabled":true,"monthly_budget_micros":1000}',0))->'preferences'->>'revision','1','Enable saves atomically');
select is(public.save_ai_preferences(public.ai_workspace()->'preferences',0),null::jsonb,'Stale settings rejected');
select throws_ok($$select public.save_ai_preferences((public.ai_workspace()->'preferences') || '{"monthly_budget_micros":0.5}',1)$$,'22023','invalid_ai_budget','Fractional micros rejected');
reset role;
set local role service_role;
select lives_ok($$select set_config('test.ai_usage',public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','claude-haiku-4-5-20251001',600,3000000)::text,true)$$,'Server reserves request');
select throws_ok($$select public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','claude-haiku-4-5-20251001',600,3000000)$$,'P0001','ai_budget_exceeded','Existing reservation counts towards cap');
select is(public.finish_ai_usage(current_setting('test.ai_usage')::uuid,'completed',9,4,null),true,'Completion recorded');
select is((select charged_micros from public.ai_usage where id=current_setting('test.ai_usage')::uuid),29::bigint,'Haiku input and output costs reconciled');
select is(public.finish_ai_usage(current_setting('test.ai_usage')::uuid,'failed',null,null,null),false,'Completion is idempotent and immutable');
select throws_ok($$select public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','claude-haiku-4-5-20251001',100,100)$$,'P0001','ai_budget_exceeded','Server total cap enforced');
select throws_ok($$select public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','photo_analysis','claude-haiku-4-5-20251001',100,3000000)$$,'42501','ai_disabled','Disabled feature blocked before spending');
select throws_ok($$select public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','unknown',100,3000000)$$,'22023','invalid_ai_reservation','Unknown model cannot use wrong pricing');
select set_config('test.ai_uncertain',public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','claude-haiku-4-5-20251001',100,3000000)::text,true);
select is(public.finish_ai_usage(current_setting('test.ai_uncertain')::uuid,'uncertain',null,null,'provider_interrupted'),true,'Uncertain request marked');
select is((select charged_micros from public.ai_usage where id=current_setting('test.ai_uncertain')::uuid),100::bigint,'Uncertain request retains full reservation');
reset role;
set local role authenticated;
select is(public.ai_workspace()->>'month_charged_micros','129','User sees actual plus uncertain spend');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000099',true);
select is((select count(*) from public.ai_usage),0::bigint,'Other user cannot read usage');
select is((select count(*) from public.ai_preferences),0::bigint,'Other user cannot read preferences');
select is(public.ai_workspace()->>'month_charged_micros','0','Workspace isolates user totals');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.save_ai_preferences((public.ai_workspace()->'preferences') || '{"enabled":false}',1);
reset role;
set local role service_role;
select throws_ok($$select public.reserve_ai_usage('10000000-0000-0000-0000-000000000001','connection','claude-haiku-4-5-20251001',100,3000000)$$,'42501','ai_disabled','Global opt-out stops future requests');
reset role;
select ok(not has_function_privilege('anon','public.ai_workspace()','execute'),'Anonymous workspace denied');
select ok(not has_table_privilege('authenticated','public.ai_usage','update'),'Direct client billing mutation denied');
select * from finish();
rollback;
